import sys; sys.path.insert(0, "tools")
from gen_lib import maker
S, M, save = maker("bc03", 303)
# ---------- QCS (60) ----------
S("definition","membrane plasmique : membrane qui délimite la cellule","Comment appelle-t-on la membrane qui délimite la cellule ?","La membrane plasmique",["La membrane nucléaire","Le tonoplaste","La paroi"],"Les membranes des organites portent le nom de l’organite concerné.",3)
S("definition","organisation des membranes","Comment les membranes cellulaires sont-elles organisées ?","En doubles couches phospholipidiques où s’insèrent, de façon asymétrique et inhomogène, d’autres structures",["En monocouches de protéines","En couches de sucres","En une seule couche symétrique de lipides"],"Ces structures caractérisent chaque membrane.",3)
S("chiffre","feuillet clair : 3 nm","En microscopie électronique, quelle est l’épaisseur du feuillet clair d’une membrane ?","3 nm",["2,5 nm","8 nm","30 nm"],"Il est entouré de deux feuillets sombres de 2,5 nm.",3)
S("chiffre","feuillets polaires : 2,5 nm","Quelle est l’épaisseur de chacun des deux feuillets polaires (sombres) d’une membrane ?","2,5 nm",["3 nm","8 nm","0,25 nm"],"Le feuillet apolaire mesure 3 nm.",20)
S("definition","triple feuillet : polaires autour d’un apolaire","Comment est constitué le triple feuillet d’une membrane ?","Deux couches polaires (osmiophiles) de part et d’autre d’une couche apolaire (osmiophobe)",["Deux couches apolaires de part et d’autre d’une couche polaire","Trois couches de protéines","Une couche de glucides entre deux couches de lipides"],"C’est l’aspect observé en microscopie électronique.",18)
S("definition","revêtement procaryote : membrane, paroi, capsule","De quoi est formé le revêtement cellulaire des cellules procaryotes ?","De la membrane plasmique, de la paroi et de la capsule",["De la membrane plasmique et du cell coat uniquement","De la paroi et du glycocalyx","De la membrane nucléaire et de la paroi"],"La capsule est inconstante.",6)
S("definition","membrane plasmique procaryote : perméabilité sélective","Quel rôle joue la membrane plasmique procaryote ?","Elle assure la perméabilité sélective : des perméases commandent les entrées",["Elle fabrique uniquement la paroi","Elle contient le noyau","Elle réalise la photosynthèse"],"Elle intervient aussi dans l’exportation de substances comme les toxines et les enzymes.",7)
S("chiffre","membrane plasmique procaryote : 8 nm","Quelle est l’épaisseur moyenne de la membrane plasmique procaryote ?","8 nm",["80 nm","0,8 nm","8 µm"],"Elle est épaisse de 8 nm en moyenne.",7)
S("definition","rôle de la paroi bactérienne","Quel rôle joue la paroi bactérienne ?","Elle protège la cellule, maintient la pression osmotique et confère sa forme à la bactérie",["Elle réalise la respiration","Elle contient le chromosome","Elle fabrique les lipides"],"C’est une structure de protection, un exosquelette.",9)
S("definition","coloration de Gram : deux groupes de bactéries","Que permet la coloration de Gram ?","Distinguer deux grands groupes de bactéries selon leur paroi",["Compter les mitochondries","Colorer le noyau en violet","Mesurer la pression osmotique"],"Les bactéries Gram+ retiennent le colorant, les Gram− non.",9)
S("definition","Gram+ retiennent le colorant","Quelles bactéries retiennent le colorant de Gram ?","Les bactéries Gram+ (Gram positif)",["Les bactéries Gram− (Gram négatif)","Toutes les bactéries","Aucune bactérie"],"L’appartenance à l’une ou l’autre classe dépend de la structure de la paroi.",9)
S("definition","peptidoglycane : filet autour de la cellule","Comment s’appelle la molécule qui entoure la cellule bactérienne tel un énorme filet ?","Le peptidoglycane",["La cellulose","La chitine","Le cholestérol"],"Il repose directement sur la membrane plasmique.",12)
S("definition","peptidoglycane ancré par l’acide téichoïque","Par quelles molécules le peptidoglycane est-il ancré dans la membrane plasmique ?","Des molécules d’acide téichoïque",["Des histones","Des aquaporines","Des phospholipides sulfatés"],"Il est maintenu par des polysaccharides anioniques.",12)
S("definition","capsule : polysaccharides","De quoi est formée la capsule bactérienne ?","De polysaccharides, d’épaisseur variable et à activité antigénique",["De cellulose","De phospholipides","De protéines contractiles"],"Elle est située en dehors de la paroi.",15)
S("definition","pili : reproduction sexuée et fixation","Dans quoi les pili bactériens sont-ils impliqués ?","La reproduction sexuée et la fixation de bactéries pathogènes aux tissus humains",["La photosynthèse","La digestion intracellulaire","La synthèse des lipides"],"Exemple : les pili d’Escherichia coli.",16)
S("definition","asymétrie de la membrane plasmique","Qu’indique l’épaisseur plus importante du feuillet polaire externe ?","L’asymétrie de la membrane plasmique",["Une zone de fusion","La présence d’un noyau","L’absence de protéines"],"L’asymétrie est aussi soulignée par la présence du cell coat côté externe.",20)
S("definition","cell coat : feutrage de fibrilles","Qu’est-ce que le cell coat (ou glycocalyx) ?","Un feutrage de fibrilles, en relation avec le milieu extracellulaire, qui revêt le feuillet externe",["Une couche de lipides interne","Une paroi cellulosique","Un organite"],"Il est aussi appelé manteau cellulaire.",21)
S("definition","fibrilles du cell coat perpendiculaires","Comment sont disposées les fibrilles du cell coat par rapport à la membrane ?","Perpendiculairement à sa surface",["Parallèlement à sa surface","En boucles dans le cytoplasme","En spirale autour du noyau"],"Leur diamètre est de 1,5 nm.",22)
S("definition","organites : triple feuillet sans cell coat","Les membranes des organites présentent-elles un cell coat ?","Non : elles ont une structure en triple feuillet, mais sans cell coat",["Oui, toujours","Oui, seulement celle des mitochondries","Oui, seulement celle du noyau"],"La similitude est morphologique, pas biochimique ni fonctionnelle.",23)
S("intrus","ribosomes sans triple feuillet","Quelle structure n’est pas limitée par un triple feuillet ?","Les ribosomes",["Les mitochondries","Les lysosomes","Le noyau"],"Le centre cellulaire, les ribosomes et le cytosquelette font exception.",23)
S("definition","cholestérol entre les phospholipides","Où se place le cholestérol dans le modèle en mosaïque ?","Entre les phospholipides",["À l’extérieur de la membrane","Dans le cytosol","Dans le noyau"],"Le modèle comprend aussi des protéines et des polysaccharides.",26)
S("definition","groupes apolaires dans le feuillet médian","Où se situent les groupes apolaires des lipides membranaires ?","Dans le feuillet médian osmiophobe",["Sur la face externe","Sur la face interne","Dans le cell coat"],"Les groupes polaires occupent les faces externe et interne.",27)
S("definition","chaînes carbonées perpendiculaires","Comment sont orientées les chaînes carbonées des lipides ?","Perpendiculairement à la surface des deux feuillets",["Parallèlement à la surface","En hélice autour de la membrane","Au hasard"],"Elles se situent dans l’espace séparant les deux feuillets.",27)
S("chiffre","composition de la membrane des hématies","Quelle est la composition de la membrane des hématies humaines ?","52 % de protéines, 40 % de lipides, 8 % de sucres",["8 % de protéines, 40 % de lipides, 52 % de sucres","40 % de protéines, 52 % de lipides, 8 % de sucres","80 % de lipides, 10 % de protéines, 10 % de sucres"],"Parmi les lipides : 55 % de phospholipides, 25 % de cholestérol, 20 % de glycolipides.",29)
S("chiffre","phospholipides : 55 % des lipides des hématies","Parmi les lipides de la membrane des hématies, quelle part représentent les phospholipides ?","55 %",["25 %","20 %","90 %"],"Le cholestérol représente 25 % et les glycolipides 20 %.",29)
S("definition","phospholipides : estérification du glycérol","Les phospholipides résultent de l’estérification :","du glycérol par deux acides gras et l’acide phosphorique",["du cholestérol par un acide aminé","du glucose par un acide gras","d’un acide aminé par un phosphate"],"Exemple : la phosphatidylcholine.",30)
S("definition","lipides membranaires amphipathiques","Que signifie « amphipathique » pour un lipide membranaire ?","Il possède une tête hydrophile et une queue hydrophobe",["Il est entièrement hydrophobe","Il est entièrement hydrophile","Il est chargé positivement"],"Les lipides membranaires sont des molécules amphipathiques.",32)
S("definition","tête d’un phospholipide : phosphate et groupement","De quoi est formée la tête d’un phospholipide ?","Du phosphate et d’un groupement spécialisé",["Du glycérol et des acides gras","Du cholestérol","D’un noyau stéroïde"],"La queue hydrophobe est formée du glycérol et des acides gras.",33)
S("definition","alcool ou acide aminé : identité du phospholipide","Que donnent les alcools ou les acides aminés d’un glycérophospholipide ?","L’identité et la caractéristique du phospholipide",["La couleur de la membrane","La taille de la queue hydrophobe","La fluidité seulement"],"Les glycérophospholipides associent glycérol, deux acides gras, un acide phosphorique et un alcool ou un acide aminé.",38)
S("definition","sphingomyéline : sphingosine + choline","Quel phospholipide obtient-on en associant la choline à un sphingophospholipide ?","La sphingomyéline",["La phosphatidylcholine","L’acide phosphatidique","Le cholestérol"],"Un sphingophospholipide associe sphingosine, acide gras, acide phosphorique et alcool ou acide aminé.",41)
S("definition","cholestérol : solidité et stabilité mécanique","Quel est le rôle du cholestérol dans la membrane ?","Renforcer la solidité et assurer la stabilité mécanique",["Fabriquer des protéines","Transporter les ions","Fixer les virus"],"Il se place dans la double couche lipidique.",43)
S("definition","cholestérol : cellules animales uniquement","Dans quelles cellules trouve-t-on du cholestérol membranaire ?","Uniquement dans les cellules animales",["Dans les cellules végétales et les bactéries","Dans toutes les cellules sans exception","Uniquement chez les bactéries"],"Il est absent des cellules végétales et des bactéries.",45)
S("definition","cholestérol amphiphile","Pourquoi dit-on que le cholestérol est amphiphile ?","Il possède un noyau stéroïde hydrophobe et une fonction alcool hydrophile",["Il est uniquement hydrophobe","Il est uniquement hydrophile","Il est chargé électriquement"],"Il possède aussi une queue hydrophobe.",45)
S("definition","glycolipides et groupe sanguin","Quels lipides de la membrane des globules rouges définissent le groupe sanguin ?","Les glycolipides",["Les phospholipides","Le cholestérol","Les triglycérides"],"Les glycolipides sont aussi appelés cérébrosides ou gangliosides.",46)
S("definition","structure d’un glycolipide","Comment est constitué un glycolipide ?","Sphingosine associée à un acide gras de poids moléculaire élevé, souvent liée à un sucre comme le galactose",["Glycérol et phosphate","Cholestérol et glucose","Acide aminé et alcool"],"Exemples : ganglioside et cérébroside.",47)
S("definition","REL synthétise les lipides membranaires","Quel organite synthétise les lipides de la membrane plasmique ?","Le réticulum endoplasmique lisse",["Le noyau","Les lysosomes","Les peroxysomes"],"La double couche acquiert son asymétrie au moment de la synthèse.",48)
S("definition","feuillet externe riche en glycolipides","Que contient surtout le feuillet externe de la membrane plasmique après sa synthèse ?","Des glycolipides",["Des phospholipides","Du cholestérol seul","Des protéines seules"],"Le feuillet interne contient surtout des phospholipides.",48)
S("cas_pratique","baisse de température et fluidité","Que provoque une baisse de la température sur les lipides membranaires ?","La synthèse de lipides insaturés, qui augmente la fluidité",["La synthèse de lipides saturés, qui diminue la fluidité","La destruction des phospholipides","Aucun effet"],"C’est une adaptation de la fluidité de la membrane.",48)
S("definition","intrinsèques : 70 %","Quelle part des protéines membranaires sont intrinsèques (transmembranaires) ?","Environ 70 %",["Environ 30 %","Environ 5 %","100 %"],"Les protéines extrinsèques représentent environ 30 %.",52)
S("definition","extrinsèques faiblement associées","Comment les protéines extrinsèques (périphériques) sont-elles associées à la membrane ?","Faiblement, à la surface externe ou interne",["Elles traversent la bicouche","Elles sont dans le feuillet médian","Elles sont ancrées par des hélices α"],"Elles sont localisées en dehors de la bicouche.",52)
S("definition","transmembranaires : hélices α apolaires","Comment les protéines transmembranaires sont-elles liées à la membrane ?","Par les acides aminés apolaires de leurs hélices α, au contact de l’environnement hydrophobe",["Par des liaisons faibles de surface","Par des ponts disulfure","Par des liaisons ioniques"],"Seuls des procédés drastiques permettent de les extraire.",54)
S("definition","traversées multiples","Que signifie « protéine à traversées multiples » ?","Elle traverse plusieurs fois la membrane",["Elle reste en surface","Elle traverse une seule fois","Elle ne traverse jamais la membrane"],"Les protéines à traversée unique ne la traversent qu’une fois.",56)
S("identification","P170 : résistance multiple aux drogues","Quelle protéine transmembranaire est citée en exemple pour la résistance multiple aux drogues ?","La protéine P170",["La fibronectine","La laminine","L’insuline"],"C’est une protéine à traversées multiples.",56)
S("definition","transmembranaires asymétriques","Pourquoi les protéines transmembranaires sont-elles asymétriques ?","Elles ont deux pôles hydrophiles et une partie moyenne hydrophobe",["Elles ont trois pôles polaires","Elles n’ont pas de partie hydrophobe","Elles sont dépourvues de sucres"],"Presque toutes sont glycosylées.",57)
S("definition","chaînes polysaccharidiques dans le cell coat","Où se trouvent les chaînes polysaccharidiques des protéines glycosylées ?","Dans le cell coat",["Dans le feuillet médian","Dans le cytosol","Dans le noyau"],"Presque toutes les protéines transmembranaires sont glycosylées.",57)
S("definition","GPI : face extracellulaire","Où sont situées les protéines ancrées par un GPI (glycosylphosphatidylinositol) ?","Sur la face extracellulaire de la membrane",["Sur la face intracellulaire","Dans le noyau","Dans le feuillet médian"],"Les protéines ancrées par des acides gras sont sur la face intracellulaire.",59)
S("definition","acides gras : face intracellulaire","Par quoi certaines protéines périphériques sont-elles ancrées sur la face intracellulaire ?","Par des acides gras (palmitique, myristique)",["Par un glycosylphosphatidylinositol","Par des ponts disulfure","Par des hélices α"],"L’ancrage se fait par l’intermédiaire d’acides gras.",59)
S("definition","extrinsèques : liaisons faibles","Comment les protéines extrinsèques interagissent-elles avec la membrane ?","Par des liaisons faibles : liaisons hydrogène et liaisons de Van der Waals",["Par des liaisons covalentes fortes","Par des hélices α hydrophobes","Par des ponts disulfure"],"Elles sont soit entièrement intracellulaires, soit entièrement extracellulaires.",62)
S("definition","rôles des protéines périphériques","Quels rôles les protéines périphériques procurent-elles aux membranes ?","Support mécanique, enzymes ou facteurs de transmission des signaux membranaires",["Synthèse de lipides","Transport des ions seulement","Production de lumière"],"Elles sont localisées en dehors de la bicouche.",63)
S("definition","glucides membranaires : glycoprotéines","Sous quelle forme se trouvent la plupart des glucides membranaires ?","Des glycoprotéines",["Des glycolipides","Des sucres libres","Des polysaccharides libres"],"Une petite partie seulement est sous forme de glycolipides.",66)
S("definition","protéoglycanes : jusqu’à 90 %","Que sont les protéoglycanes ?","Des glycoprotéines à polysaccharides de chaîne longue, jusqu’à 90 % du poids moléculaire",["Des glycoprotéines à courts polysaccharides","Des lipides","Des phospholipides sulfatés"],"Quand un des sucres est aminé, on parle de glycosaminoglycane.",67)
S("definition","aquaporines : passage rapide de l’eau","Par quoi l’eau traverse-t-elle rapidement la membrane ?","Les aquaporines",["Les phospholipides","La pompe Na⁺/K⁺ (sodium/potassium)","Les pili"],"À travers les phospholipides, le passage de l’eau est lent.",79)
S("definition","diffusion simple","La diffusion simple suit :","le gradient de concentration, sans énergie",["le gradient inverse, avec énergie","un récepteur spécifique","une vésicule"],"Il n’y a que quelques molécules qui traversent les membranes par simple diffusion.",74)
S("definition","diffusion facilitée : grosses molécules non liposolubles","La diffusion facilitée concerne des molécules :","de grosse taille ou non liposolubles (sucres, ions), via des protéines porteuses ou tunnels",["petites et liposolubles","uniquement l’eau","uniquement les gaz"],"Protéines porteuses (perméases) ou protéines tunnels (conductines).",76)
S("definition","transport actif : contre le gradient avec énergie","Que caractérise le transport actif ?","Un transport à l’encontre du gradient de concentration, avec une source d’énergie",["Un transport suivant le gradient, sans énergie","Un transport sans transporteur","Un passage direct entre les phospholipides"],"Il est défavorable du point de vue thermodynamique.",80)
S("definition","pompe Na+/K+ : énergie de l’ATP","Avec quelle énergie la pompe Na⁺/K⁺ (sodium/potassium) fonctionne-t-elle ?","L’énergie de l’ATP (adénosine triphosphate)",["Le gradient de H⁺ (protons)","La lumière","Aucune énergie"],"C’est un transport actif entraîné par l’énergie de l’ATP.",82)
S("definition","transport actif secondaire : co-transport","Qu’est-ce qu’un transport actif secondaire ?","Un co-transport où l’énergie d’un soluté favorable sert à transporter un soluté défavorable",["Un transport passif sans protéine","Une exocytose","Une phagocytose"],"Exemple : le co-transport H⁺/saccharose.",84)
S("definition","exocytose : fusion avec une vésicule interne","En quoi consiste l’exocytose ?","À fusionner la membrane plasmique avec une vésicule d’origine interne",["À former une vésicule par invagination de la membrane","À digérer des particules","À créer un pore nucléaire"],"Elle permet la sécrétion de produits fabriqués par la cellule.",92)
S("definition","pinocytose : puits recouverts","Que forme la pinocytose ?","Des puits recouverts et de petites vésicules recouvertes",["De très grosses vésicules","Des pores","Des cils"],"Les puits mesurent 0,2 à 0,5 µm de diamètre.",93)
S("definition","phagocytose : cellules entières","Quel type d’endocytose permet d’absorber des cellules entières ?","La phagocytose",["La pinocytose","L’exocytose","La diffusion facilitée"],"Elle implique l’internalisation de vésicules de très grande taille.",93)

